"""Synthetic auditory tasks whose inputs are generated by the periphery model."""

import numpy as np
import torch
from torch.utils.data import TensorDataset

from .. import stimuli
from ..periphery import AuditoryPeriphery, cochleagram


def make_pitch_dataset(n_samples, f0s=None, fs=16000, duration=0.2, n_channels=48,
                       f_min=80.0, f_max=6000.0, frame_rate=200.0, snr_db=(5, 30),
                       level_db=(50, 70), f0_jitter=0.015, missing_fundamental_prob=0.3,
                       seed=0):
    """Generate cochleagrams of harmonic complexes labelled by F0 class.

    Each sample randomises level, harmonic phases, background noise and, with
    probability ``missing_fundamental_prob``, removes the lowest harmonics so the
    network must learn pitch from the harmonic pattern ("missing fundamental").

    Returns X (n, n_channels, n_frames) float32, y (n,) int64, and metadata dict.
    """
    rng = np.random.default_rng(seed)
    # default: 25 classes one semitone apart, 100-400 Hz (two octaves)
    f0s = 100 * 2 ** (np.arange(25) / 12) if f0s is None else np.asarray(f0s)
    per = AuditoryPeriphery(fs, n_channels, f_min, f_max)
    X, y = [], []
    for _ in range(n_samples):
        label = rng.integers(len(f0s))
        f0 = f0s[label] * (1 + rng.uniform(-f0_jitter, f0_jitter))
        lowest = rng.integers(2, 5) if rng.random() < missing_fundamental_prob else 1
        x = stimuli.harmonic_complex(f0, duration, fs, n_harmonics=40, lowest_harmonic=lowest,
                                     level_db=rng.uniform(*level_db), phases="random",
                                     max_freq=f_max, rng=rng)
        x = stimuli.add_noise(x, rng.uniform(*snr_db), rng=rng)
        _, _, C = cochleagram(x, fs, frame_rate=frame_rate, periphery=per)
        X.append(C)
        y.append(label)
    X = np.stack(X).astype(np.float32)
    X = (X - 40.0) / 20.0  # fixed dB scaling so train/test sets share normalisation
    meta = dict(f0s=f0s, cfs=per.cfs, fs=fs, frame_rate=frame_rate)
    return X, np.asarray(y, dtype=np.int64), meta


class SyntheticPitchDataset(TensorDataset):
    """TensorDataset wrapper around :func:`make_pitch_dataset`."""

    def __init__(self, n_samples, **kwargs):
        X, y, self.meta = make_pitch_dataset(n_samples, **kwargs)
        super().__init__(torch.from_numpy(X), torch.from_numpy(y))
